using System.Globalization;
namespace QuanLyNhaHang.Models;
public static class Currency { public static string Money(decimal value) => value.ToString("N0",CultureInfo.GetCultureInfo("vi-VN"))+" đ"; }
public class DiningTable { public int Id {get;set;} public string Name {get;set;}=""; public int Seats {get;set;} public string Status {get;set;}="Trống"; public DateTime? Opened {get;set;} public List<OrderLine> Orders {get;set;}=new(); public decimal Total=>Orders.Sum(x=>x.Total); }
public class Food { public int Id {get;set;} public string Code=>"M"+Id.ToString("000"); public string Name {get;set;}=""; public string Category {get;set;}="Món chính"; public string Unit {get;set;}="phần"; public decimal Price {get;set;} public bool Active {get;set;}=true; public string Status=>Active?"Đang bán":"Ngừng bán"; public string PriceText=>Currency.Money(Price); }
public record OrderLine(int FoodId,string Name,decimal Price,int Quantity) { public decimal Total=>Price*Quantity; public string TotalText=>Currency.Money(Total); }
public class Bill { public string Id {get;set;}=""; public int TableId {get;set;} public string TableName {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.Now; public DateTime? PaidAt {get;set;} public string Created=>CreatedAt.ToString("dd/MM/yyyy HH:mm"); public List<OrderLine> Items {get;set;}=new(); public decimal Subtotal=>Items.Sum(x=>x.Total); public int Discount {get;set;} public decimal Due=>Math.Round(Subtotal*(100-Discount)/100,0,MidpointRounding.AwayFromZero); public string SubtotalText=>Currency.Money(Subtotal); public string DueText=>Currency.Money(Due); public bool Paid=>PaidAt.HasValue; public string Status=>Paid?"Đã thanh toán":"Chờ thanh toán"; public string Method {get;set;}="Tiền mặt"; }
public class Stock { public string Name {get;set;}=""; public string Unit {get;set;}="kg"; public decimal Quantity {get;set;} public decimal Min {get;set;} public string Status=>Quantity==0?"Hết hàng":Quantity<Min?"Sắp hết":"Bình thường"; }
public class Employee { public string Id {get;set;}=""; public string Name {get;set;}=""; public DateTime? Birthday {get;set;} public string Gender {get;set;}="Nam"; public string Phone {get;set;}=""; public string Email {get;set;}=""; public string Address {get;set;}=""; public string Role {get;set;}="Phục vụ"; public string Status {get;set;}="Đang làm việc"; public string AccountCode {get;set;}=""; public string Username {get;set;}=""; public string AccountStatus {get;set;}="Hoạt động"; }
public record Activity(string At,string Who,string Detail);
public class DemoState {
 public List<DiningTable> Tables {get;}=new(); public List<Food> Foods {get;}=new(); public List<Bill> Bills {get;}=new(); public List<Stock> Stocks {get;}=new(); public List<Employee> Staff {get;}=new(); public List<Activity> Logs {get;}=new(); public List<string> Messages {get;}=new(){"Thu ngân: Bàn 02 cần kiểm tra hóa đơn nhé.","Phục vụ: Mình đã cập nhật món mới."}; public List<object> Requests {get;}=new();
 public DemoState(){string[] status={"Trống","Có Khách","Có Khách","Trống","Chờ Dọn","Đã Đặt","Trống","Có Khách","Trống","Có Khách","Đã Đặt","Trống"};int[] seats={4,6,4,8,4,2,6,4,2,6,4,8};for(int i=0;i<12;i++)Tables.Add(new(){Id=i+1,Name=$"Bàn {i+1:00}",Seats=seats[i],Status=status[i],Opened=status[i]=="Có Khách"?DateTime.Today.AddHours(18).AddMinutes(20):null});
 string[] names={"Gà chiên giòn","Khoai tây chiên","Cơm chiên hải sản","Mì xào bò","Rau xào tỏi","Nước ngọt","Trà đá"};decimal[] prices={95000,45000,89000,85000,39000,25000,10000};string[] cats={"Món chính","Món ăn kèm","Món chính","Món chính","Món ăn kèm","Đồ uống","Đồ uống"};for(int i=0;i<names.Length;i++)Foods.Add(new(){Id=i+1,Name=names[i],Price=prices[i],Category=cats[i],Unit=i>=5?"ly/lon":"phần"});Add(Tables[1].Orders,Foods[0],2);Add(Tables[1].Orders,Foods[1],1);Add(Tables[1].Orders,Foods[5],3);Add(Tables[2].Orders,Foods[3],1);Add(Tables[7].Orders,Foods[2],2);Add(Tables[9].Orders,Foods[6],5);
 Stocks.AddRange(new Stock[]{new(){Name="Thịt bò",Unit="kg",Quantity=8,Min=5},new(){Name="Rau xà lách",Unit="kg",Quantity=2,Min=5},new(){Name="Dầu ăn",Unit="lít",Quantity=0,Min=3},new(){Name="Nước ngọt",Unit="thùng",Quantity=15,Min=8}});
 string[] sn={"Nguyễn Văn A","Trần Thị B","Lê Văn C"};string[] roles={"Phục vụ","Thu ngân","Quản lý"};string[] users={"phucvu01","thungan02","quanly03"};for(int i=0;i<3;i++)Staff.Add(new(){Id=$"NV{i+1:00}",Name=sn[i],Role=roles[i],Username=users[i],AccountCode=$"TK{i+1:000}",Birthday=new DateTime(2000-i,6,18),Gender=i==1?"Nữ":"Nam",Phone=$"090123456{i}",Email=$"nv{i+1:00}@example.local",Address="TP. Hồ Chí Minh"});}
 public Bill? Pending(int id)=>Bills.LastOrDefault(x=>x.TableId==id&&!x.Paid);
 public static void Add(List<OrderLine> lines,Food food,int qty=1){int i=lines.FindIndex(x=>x.FoodId==food.Id&&x.Price==food.Price);if(i<0)lines.Add(new(food.Id,food.Name,food.Price,qty));else lines[i]=lines[i] with {Quantity=lines[i].Quantity+qty};}
 public static void Adjust(List<OrderLine> lines,OrderLine line,int delta){int i=lines.IndexOf(line);if(i<0)return;int q=lines[i].Quantity+delta;if(q<=0)lines.RemoveAt(i);else lines[i]=lines[i] with {Quantity=q};}
}
